	/// </summary>
	ExternalModel,
	/// <summary>
	/// <c>FULLTEXT CATALOG::</c>
	/// </summary>
	FulltextCatalog,
	/// <summary>
	/// <c>FULLTEXT STOPLIST::</c>
	/// </summary>
	FulltextStoplist,
	/// <summary>
	/// <c>LOGIN::</c>
	/// </summary>
	Login,
	/// <summary>
	/// <c>MESSAGE TYPE::</c>
	/// </summary>
	MessageType,
	/// <summary>
	/// <c>OBJECT::</c>
	/// </summary>
	Object,
	/// <summary>
	/// <c>REMOTE SERVICE BINDING::</c>
	/// </summary>
	RemoteServiceBinding,
	/// <summary>
	/// <c>ROLE::</c>
